#pragma once
namespace iah {
inline const char* renderBridgeSettingsPage(){return R"IAH(<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta charset="utf-8"><title>iPhone Agent Bridge</title><style>html{color-scheme:light dark;font:17px system-ui}body{max-width:540px;margin:36px auto;padding:0 20px}h1{font-size:25px}label{display:block;margin:20px 0 7px}input:not([type=checkbox]),button{box-sizing:border-box;font:inherit;padding:12px;width:100%;border:1px solid #aaa;border-radius:10px}button{margin-top:22px;cursor:pointer}input[type=checkbox]{width:20px;height:20px;vertical-align:middle}p{line-height:1.5;overflow-wrap:anywhere}code{overflow-wrap:anywhere}#status{white-space:pre-wrap}a{display:block;margin-top:18px}</style></head><body><h1>iPhone Agent Bridge</h1><p id="status" role="status"></p><form id="login" hidden><label id="codeLabel" for="code"></label><input id="code" type="password" autocomplete="current-password"><button id="connect"></button></form><form id="settings" hidden><label id="hostLabel" for="hostname"></label><input id="hostname" required pattern="[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?" maxlength="63" autocomplete="off" autocapitalize="none" spellcheck="false"><p id="address"></p><label><input id="required" type="checkbox"> <span id="requiredLabel"></span></label><p id="codeDisplay" hidden><span id="savedCodeLabel"></span><br><code id="savedCode"></code></p><button id="save"></button></form><a id="next" hidden></a><script>
const messages={
'en':['Bridge settings','Connecting…','Connection code','Connect','Local device name','Require a connection code','Save','Connection code','Saved.','Saved. The bridge is restarting. Open its new address shortly.','Stop the current task before changing settings.','Connection failed.','Invalid connection code.','Open bridge settings'],
'zh-Hans':['桥接器设置','正在连接…','设备连接码','连接','局域网设备名','启用设备连接码','保存','设备连接码','已保存。','已保存，桥接器正在重启。稍后打开新地址。','请先停止当前任务，再修改设置。','连接失败。','设备连接码不正确。','打开桥接器设置'],
'zh-Hant':['橋接器設定','正在連線…','裝置連線碼','連線','區域網路裝置名稱','啟用裝置連線碼','儲存','裝置連線碼','已儲存。','已儲存，橋接器正在重新啟動。稍後開啟新位址。','請先停止目前的任務，再修改設定。','連線失敗。','裝置連線碼不正確。','開啟橋接器設定'],
'ja':['ブリッジ設定','接続中…','接続コード','接続','ローカルデバイス名','接続コードを使用','保存','接続コード','保存しました。','保存しました。ブリッジの再起動後、新しいアドレスを開いてください。','設定を変更する前に現在のタスクを停止してください。','接続できませんでした。','接続コードが正しくありません。','ブリッジ設定を開く'],
'ru':['Настройки моста','Подключение…','Код подключения','Подключить','Имя устройства в локальной сети','Использовать код подключения','Сохранить','Код подключения','Сохранено.','Сохранено. Мост перезапускается. Затем откройте новый адрес.','Остановите текущую задачу перед изменением настроек.','Не удалось подключиться.','Неверный код подключения.','Открыть настройки моста'],
'de':['Bridge-Einstellungen','Verbindung wird hergestellt…','Verbindungscode','Verbinden','Lokaler Gerätename','Verbindungscode verwenden','Speichern','Verbindungscode','Gespeichert.','Gespeichert. Die Bridge startet neu. Öffne anschließend die neue Adresse.','Beende die laufende Aufgabe, bevor du Einstellungen änderst.','Verbindung fehlgeschlagen.','Ungültiger Verbindungscode.','Bridge-Einstellungen öffnen'],
'fr':['Réglages du pont','Connexion…','Code de connexion','Se connecter','Nom local de l’appareil','Utiliser un code de connexion','Enregistrer','Code de connexion','Enregistré.','Enregistré. Le pont redémarre. Ouvrez ensuite sa nouvelle adresse.','Arrêtez la tâche en cours avant de modifier les réglages.','Échec de la connexion.','Code de connexion incorrect.','Ouvrir les réglages du pont'],
'es':['Ajustes del puente','Conectando…','Código de conexión','Conectar','Nombre local del dispositivo','Usar código de conexión','Guardar','Código de conexión','Guardado.','Guardado. El puente se está reiniciando. Después, abre la nueva dirección.','Detén la tarea actual antes de cambiar los ajustes.','No se pudo conectar.','Código de conexión incorrecto.','Abrir ajustes del puente']};
const locale=(navigator.languages||[navigator.language||'en'])[0],language=/^zh/i.test(locale)?(/Hant|TW|HK|MO/i.test(locale)?'zh-Hant':'zh-Hans'):(locale.split('-')[0] in messages?locale.split('-')[0]:'en'),m=messages[language],el=id=>document.getElementById(id);document.documentElement.lang=language;document.title=m[0]+' · iPhone Agent Bridge';
for(const [id,index] of Object.entries({status:1,codeLabel:2,connect:3,hostLabel:4,requiredLabel:5,save:6,savedCodeLabel:7,next:13}))el(id).textContent=m[index];
let token='',clientId='';try{token=sessionStorage.getItem('iah-manager-token')||'';clientId=localStorage.getItem('iah-manager-client')||'';}catch{}
if(!/^[a-z0-9-]{1,80}$/.test(clientId)){clientId='manager-'+Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');try{localStorage.setItem('iah-manager-client',clientId);}catch{}}
async function request(path,method='GET',body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(path,{method,cache:'no-store',signal:controller.signal,headers:{'X-Harness-Window':'1',...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const value=await response.json();if(!response.ok)throw Object.assign(new Error(value.error||m[11]),{status:response.status});return value;}finally{clearTimeout(timer);}}
function errorMessage(error){return error.message==='board_busy'?m[10]:error.message==='connection_code_invalid'?m[12]:m[11];}
function show(value){el('settings').hidden=false;el('login').hidden=true;el('hostname').value=value.hostname;el('required').checked=value.pairingCodeRequired;el('savedCode').textContent=value.pairingCodeRequired?value.connectionCode:'';el('codeDisplay').hidden=!value.pairingCodeRequired;el('address').textContent='http://'+value.hostname+'.local';el('status').textContent='';}
async function connect(){const identity=await request('/v1/identity');if(token){try{show(await request('/v1/settings'));return;}catch(error){if(error.status!==401)throw error;token='';try{sessionStorage.removeItem('iah-manager-token');}catch{}}}if(identity.pairingCodeRequired&&!el('code').value){el('login').hidden=false;el('status').textContent='';return;}const paired=await request('/v1/pair','POST',{clientId,setupPassword:el('code').value});token=paired.token;try{sessionStorage.setItem('iah-manager-token',token);}catch{}show(await request('/v1/settings'));el('code').value='';}
el('login').onsubmit=async event=>{event.preventDefault();el('connect').disabled=true;try{await connect();}catch(error){el('status').textContent=errorMessage(error);}finally{el('connect').disabled=false;}};
el('settings').onsubmit=async event=>{event.preventDefault();el('save').disabled=true;try{const result=await request('/v1/settings','POST',{hostname:el('hostname').value.trim().toLowerCase(),pairingCodeRequired:el('required').checked});show(result);el('status').textContent=m[result.restartRequired?9:8];if(result.restartRequired){el('save').hidden=true;el('hostname').disabled=true;el('required').disabled=true;el('next').href=result.newURL+'/settings';el('next').hidden=false;}}catch(error){el('status').textContent=errorMessage(error);}finally{el('save').disabled=false;}};
connect().catch(error=>{el('status').textContent=errorMessage(error);el('login').hidden=false;});
</script></body></html>)IAH";}
}
